mapper.select:
SELECT rob.id, rob.cell_sha256_code_list,rob.package_id,rob.retry_count FROM b_xiecheng_colliding_data_rob rob JOIN b_xiecheng_colliding_data_package pkg ON rob.package_id = pkg.id WHERE pkg.is_delete = 0
AND rob.package_id IN
#{id}
AND rob.is_delete = 0 AND rob.retry_count = 0 and pkg.colliding_time <= now() AND (DATE(rob.push_time) != CURDATE() OR rob.push_time IS NULL) ORDER BY pkg.priority desc limit #{pageSize}

select *
from b_xiecheng_colliding_data_rob
where is_delete = 1
     and push_time < #{startTime}
order by push_time asc limit #{size};

mapper.delete:
delete
from b_xiecheng_colliding_data_rob
where id in

    #{id}

limit #{size};

mapper.select:
select * from b_xiecheng_colliding_data_rob where is_delete = 0
and retry_count = 3
and retry_count > 0 and retry_count < 3
and id > #{minId}
order by id asc limit #{pageSize};

select a.cell_sha256_code_list, max(c.colliding_end_time) from b_xiecheng_colliding_data_rob a join b_xiecheng_colliding_data_package b on b.id = a.package_id join b_xiecheng_colliding_data_package_rule c on b.id = c.package_id where a.is_delete = 0 and b.is_delete = 0 and c.is_delete = 0 and a.cell_sha256_code_list in
#{cell}
group by a.cell_sha256_code_list
